=== reservations/ReservationService.java
     1	package hotel.reservations;
     2	
     3	import hotel.documents.DocumentTexts;
     4	import hotel.documents.ReservationReceipt;
     5	import hotel.messages.EmailSender;
     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	
    20	    public ReservationService(
    21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.emailSender = emailSender;
    26	    }
    27	
    28	    public synchronized Reservation create(NewReservation request) {
    29	        if (!request.checkOut().isAfter(request.checkIn())) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    31	        }
    32	        if (request.guests() < 1) {
    33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    34	        }
    35	        Room room = rooms.find(request.roomNumber())
    36	                .orElseThrow(() -> new HotelException(
    37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    38	        if (request.guests() > room.capacity()) {
    39	            throw new HotelException(
    40	                    ErrorCode.CAPACITY_EXCEEDED,
    41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    42	        }
    43	        boolean roomTaken = store.all().stream()
    44	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    45	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    46	        if (roomTaken) {
    47	            throw new HotelException(
    48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    49	        }
    50	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    51	        Reservation reservation = new Reservation(store.nextId(), request, price);
    52	        store.save(reservation);
    53	        return reservation;
    54	    }
    55	
    56	    public Reservation find(long reservationId) {
    57	        return store.find(reservationId)
    58	                .orElseThrow(() -> new HotelException(
    59	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    60	    }
    61	
    62	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    63	    public synchronized Reservation confirm(long reservationId) {
    64	        Reservation reservation = find(reservationId);
    65	        if (reservation.status() != ReservationStatus.PENDING) {
    66	            throw notAllowed(reservation, "confirm");
    67	        }
    68	        reservation.confirmPayment();
    69	        Room room = roomOf(reservation);
    70	        ReservationReceipt receipt;
    71	        if (reservation.guest().isCompany()) {
    72	            receipt = new ReservationReceipt("Fatura de hospedagem", reservation, room,
    73	                    DocumentTexts.companyInvoice(reservation, room));
    74	        } else if (reservation.guest().isForeigner()) {
    75	            receipt = new ReservationReceipt("Booking receipt", reservation, room,
    76	                    DocumentTexts.foreignReceipt(reservation, room));
    77	        } else {
    78	            receipt = new ReservationReceipt("Comprovante de reserva", reservation, room,
    79	                    DocumentTexts.personReceipt(reservation, room));
    80	        }
    81	        emailSender.send(
    82	                reservation.guest().email(),
    83	                "Reserva confirmada - " + HOTEL_NAME,
    84	                confirmationEmailBody(reservation, receipt));
    85	        return reservation;
    86	    }
    87	
    88	    /**
    89	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    90	     * reservation was never paid, so nothing comes back).
    91	     */
    92	    public synchronized Reservation cancel(long reservationId) {
    93	        Reservation reservation = find(reservationId);
    94	        if (reservation.status() != ReservationStatus.PENDING
    95	                && reservation.status() != ReservationStatus.CONFIRMED) {
    96	            throw notAllowed(reservation, "cancel");
    97	        }
    98	        BigDecimal refund = switch (reservation.ratePlan()) {
    99	            case STANDARD -> reservation.amountPaid();
   100	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   101	        };
   102	        reservation.cancel(refund);
   103	        return reservation;
   104	    }
   105	
   106	    public synchronized Reservation checkIn(long reservationId) {
   107	        Reservation reservation = find(reservationId);
   108	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   109	            throw notAllowed(reservation, "check in");
   110	        }
   111	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   112	        return reservation;
   113	    }
   114	
   115	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   116	    public synchronized ReservationReceipt checkOut(long reservationId) {
   117	        Reservation reservation = find(reservationId);
   118	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   119	            throw notAllowed(reservation, "check out");
   120	        }
   121	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   122	        Room room = roomOf(reservation);
   123	        ReservationReceipt finalReceipt;
   124	        if (reservation.guest().isCompany()) {
   125	            finalReceipt = new ReservationReceipt("Fatura de hospedagem", reservation, room,
   126	                    DocumentTexts.companyInvoice(reservation, room));
   127	        } else if (reservation.guest().isForeigner()) {
   128	            finalReceipt = new ReservationReceipt("Booking receipt", reservation, room,
   129	                    DocumentTexts.foreignReceipt(reservation, room));
   130	        } else {
   131	            finalReceipt = new ReservationReceipt("Comprovante de reserva", reservation, room,
   132	                    DocumentTexts.personReceipt(reservation, room));
   133	        }
   134	        return finalReceipt;
   135	    }
   136	
   137	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   138	    public ReservationReceipt receiptCopy(long reservationId) {
   139	        Reservation reservation = find(reservationId);
   140	        if (!reservation.isPaid()) {
   141	            throw notAllowed(reservation, "issue a receipt for");
   142	        }
   143	        Room room = roomOf(reservation);
   144	        ReservationReceipt copy;
   145	        if (reservation.guest().isCompany()) {
   146	            copy = new ReservationReceipt("Fatura de hospedagem", reservation, room,
   147	                    DocumentTexts.companyInvoice(reservation, room));
   148	        } else if (reservation.guest().isForeigner()) {
   149	            copy = new ReservationReceipt("Booking receipt", reservation, room,
   150	                    DocumentTexts.foreignReceipt(reservation, room));
   151	        } else {
   152	            copy = new ReservationReceipt("Comprovante de reserva", reservation, room,
   153	                    DocumentTexts.personReceipt(reservation, room));
   154	        }
   155	        return copy;
   156	    }
   157	
   158	    private Room roomOf(Reservation reservation) {
   159	        return rooms.find(reservation.roomNumber()).orElseThrow();
   160	    }
   161	
   162	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   163	        return "Olá, " + reservation.guest().name() + "!\n\n"
   164	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   165	                + receipt.text() + "\n"
   166	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   167	                + "Até breve!\n";
   168	    }
   169	
   170	    private static HotelException notAllowed(Reservation reservation, String operation) {
   171	        return new HotelException(
   172	                ErrorCode.OPERATION_NOT_ALLOWED,
   173	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   174	    }
   175	}
