    60	                .append(")\n");
    61	        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    62	        int nights = reservation.price().nights();
    63	        text.append("Check-in: ").append(reservation.checkIn()).append(" | Check-out: ")
    64	                .append(reservation.checkOut()).append(" | ").append(nights)
    65	                .append(nights == 1 ? " night" : " nights").append('\n');
    66	        text.append("Nights: ").append(brl(reservation.price().subtotal())).append('\n');
