    49	
    50	/** The HTTP API the inn's website and front desk call. */
    51	public final class HttpApi {
    52	
    53	    private final Javalin server;
    54	    private final Rooms rooms;
    55	    private final ReservationService reservations;
    56	    private final SentMessages sentMessages;
    57	    private final OccupancyReport occupancyReport;
    58	    private final RevenueReport revenueReport;
    59	
    60	    public HttpApi(
    61	            Rooms rooms,
    62	            ReservationService reservations,
    63	            SentMessages sentMessages,
    64	            OccupancyReport occupancyReport,
    65	            RevenueReport revenueReport) {
    66	        this.rooms = rooms;
    67	        this.reservations = reservations;
    68	        this.sentMessages = sentMessages;
    69	        this.occupancyReport = occupancyReport;
    70	        this.revenueReport = revenueReport;
    71	
    72	        ObjectMapper jsonMapper = JsonMapper.builder()
    73	                .addModule(new JavaTimeModule())
    74	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    75	                .build();
    76	        this.server = Javalin.create(config -> {
    77	            config.showJavalinBanner = false;
    78	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    79	        });
    80	        registerRoutes();
    81	        registerErrorHandling();
    82	    }
    83	
    84	    public Javalin server() {
    85	        return server;
    86	    }
    87	
    88	    private void registerRoutes() {
    89	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    90	
    91	        server.post("/reservations", ctx -> {
    92	            NewReservation request = readNewReservation(ctx);
    93	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    94	        });
    95	        server.get("/reservations/{id}", ctx ->
    96	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    97	        server.post("/reservations/{id}/confirmation", ctx ->
    98	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    99	        server.post("/reservations/{id}/cancellation", ctx ->
   100	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
   101	        server.post("/reservations/{id}/check-in", ctx ->
   102	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
   103	        server.post("/reservations/{id}/check-out", ctx ->
   104	                ctx.json(reservations.checkOut(reservationId(ctx))));
   105	        server.get("/reservations/{id}/document", ctx ->
   106	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
   107	
   108	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
   109	
   110	        server.get("/reports/occupancy", ctx -> {
   111	            LocalDate night = readDate(ctx);
   112	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
   113	        });
   114	        server.get("/reports/revenue", ctx -> {
