   120	    private void registerErrorHandling() {
   121	        server.exception(HotelException.class, (exception, ctx) -> {
   122	            ctx.status(httpStatus(exception.errorCode()));
   123	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   124	        });
