   136	    private static NewReservation readNewReservation(Context ctx) {
   137	        CreateReservationRequest body;
   138	        try {
   139	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   140	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   142	        }
   143	        if (body == null
   144	                || body.roomNumber() == null
   145	                || isBlank(body.guestName())
   146	                || isBlank(body.guestEmail())
   147	                || body.checkIn() == null
   148	                || body.checkOut() == null
   149	                || body.guests() == null
   150	                || body.ratePlan() == null) {
   151	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   152	        }
   153	        int identifications = (isBlank(body.guestCpf()) ? 0 : 1)
   154	                + (isBlank(body.companyCnpj()) && isBlank(body.companyName()) ? 0 : 1)
   155	                + (isBlank(body.guestPassport()) && isBlank(body.guestCountry()) ? 0 : 1);
   156	        boolean companyIncomplete = isBlank(body.companyCnpj()) != isBlank(body.companyName());
   157	        boolean passportIncomplete = isBlank(body.guestPassport()) != isBlank(body.guestCountry());
   158	        if (identifications != 1 || companyIncomplete || passportIncomplete) {
   159	            throw new HotelException(ErrorCode.INVALID_REQUEST,
   160	                    "the guest needs a CPF, or a company's CNPJ and name, or a passport and country (only one)");
   161	        }
   162	        Guest guest = new Guest(body.guestName(), body.guestEmail(), nullIfBlank(body.guestCpf()),
   163	                nullIfBlank(body.companyCnpj()), nullIfBlank(body.companyName()),
   164	                nullIfBlank(body.guestPassport()), nullIfBlank(body.guestCountry()));
   165	        return new NewReservation(
   166	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   167	    }
