   127	    private static int httpStatus(ErrorCode errorCode) {
   128	        return switch (errorCode) {
   129	            case INVALID_REQUEST -> 400;
   130	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   131	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
